StructuredTextModel.Text:
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:					HE_ExplicitMessage
//	CREATOR:				Helgevold - William
// REQUIREMENTS: NX CPU
//
// DESCRTIPTION: 	Sends explicit (CIP) message based on information from "Ext_Telegram"
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION				DATE					SIGN							DESCRIPTION
//	 1.0.0					2025-10-13			William Veim				Initial release
//
//================================================================================================================================

(*************************************************************************
 *	INITIALISING VARIABELS
 *************************************************************************)

//Watch time in state - inc if too long time
IF Token_Sample = Ext_Telegram.Token_Active THEN
	TimeInState:=ADD_TIME(In1:=TimeInState, In2:=GetMyTaskInterval());
ELSE
	Token_Sample:=Ext_Telegram.Token_Active;
	TimeInState:=TIME#0ms;
END_IF;

IF TimeInState> Cfg_TimeOut THEN
	Inc(Ext_Telegram.Token_Active);
	TimeInState:=TIME#0ms;
	Ext_Telegram.Execute:=FALSE;
END_IF;

Err_ArrayOutOfBound:= Ext_Telegram.Token_Static[UPPER_BOUND(Ext_Telegram.Token_Static,1)];

(*************************************************************************
 *	EXCECUTING CIP BLOCK
 *************************************************************************)

//Ready for request 
Ext_Telegram.Ready:=NOT FB_CIPUCMMSend.Execute AND NOT FB_CIPUCMMSend.Busy;

FB_CIPUCMMSend(Execute:=Ext_Telegram.Execute AND NOT FB_CIPUCMMSend.Busy, 
								RoutePath:=Ext_Telegram.RoutePath, 
								TimeOut:=LINT_TO_UINT(TimeToSec(Cfg_TimeOut)), 
								ServiceCode:=Ext_Telegram.ServiceCode, 
								RqPath:=Ext_Telegram.ReqPath, 
								ServiceDat:=Ext_Telegram.ServiceData, 
								Size:=Ext_Telegram.Size, 
								RespServiceDat:=Ext_Telegram.RespServiceData.DWrd, 
								Done=>Ext_Telegram.Sucsess, 
								Error=>Ext_Telegram.Error, 
								ErrorID=>Ext_Telegram.ErrorID, 
								ErrorIDEx=>Ext_Telegram.ErrorIDEx, 
								RespSize=>Ext_Telegram.RespSize);

IF NOT Ext_Telegram.Token_Static[Ext_Telegram.Token_Active] THEN
	Ext_Telegram.Token_Active:=0;
END_IF;
